#!/usr/bin/env python3
"""Fix singular-matrix and invalid-trial failures after the ed22663 SG patches.

Run from ros/examples/grape-param-estim/minimal or pass that directory.

This patch:
- uses Moore-Penrose pseudoinverse for rigid-body inertia application storage;
- uses pseudoinverse for prior/posterior precision covariance and mean solves;
- rejects floating-point-invalid optimizer trial points instead of aborting;
- records invalid trial counts/types/examples in optimizer diagnostics;
- keeps the scientific 14-D chart unbounded;
- creates no backup files.
"""

from __future__ import annotations
import argparse
import base64
import hashlib
import os
from pathlib import Path
import py_compile
import subprocess
import tempfile
import zlib

EXPECTED = {
    "deterministic_savgol_dynamics_estimator.py": "5d2b5fc9f3a3b1a58ec99160ce9d73b67599ee2c",
    "savgol_dynamics_confidence.py": "4783f0453f943c1bca14e6df8292d7f0071b6e06",
    "deterministic_savgol_dynamics_data_dictionary.md": "1eedcc6e6064de6ba192a5d8691c5e42a9ef113d",
    "../src/grape_param_estim/dynamics.py": "67c36ed58d4568d8d5611e431eece8c5c143b8d9",
    "spline_dynamics_confidence.py": "be53b0dacff0f68bf100406225a7367f7b7a1ef7"
}
FULL_PAYLOADS = {
    "deterministic_savgol_dynamics_estimator.py": "",
    "savgol_dynamics_confidence.py": "",
    "deterministic_savgol_dynamics_data_dictionary.md": "",
    "../src/grape_param_estim/dynamics.py": ""
}
FULL_NEW_SHA = {
    "deterministic_savgol_dynamics_estimator.py": "46cdf94af9fbfeb35b1e21ce149b3178bad1f491",
    "savgol_dynamics_confidence.py": "7e9e2200ec7372a09fa75dbfd701bf40e053cb9f",
    "deterministic_savgol_dynamics_data_dictionary.md": "1eedcc6e6064de6ba192a5d8691c5e42a9ef113d",
    "../src/grape_param_estim/dynamics.py": "a7f8cf3c22435399a9974dd45bb74ecc57e12af8"
}
LEGACY_REPLACEMENTS = [('    prior_covariance = np.linalg.inv(prior_precision)\n', '    prior_covariance = np.linalg.pinv(prior_precision, hermitian=True)\n'), ('    posterior_covariance = np.linalg.inv(posterior_precision)\n', '    posterior_covariance = np.linalg.pinv(posterior_precision, hermitian=True)\n'), ('    posterior_delta_mean = np.linalg.solve(\n        posterior_precision,\n        posterior_information_vector,\n    )\n', '    posterior_delta_mean = (\n        posterior_covariance @ posterior_information_vector\n    )\n')]

def git_blob_sha(data: bytes) -> str:
    return hashlib.sha1(
        b"blob " + str(len(data)).encode("ascii") + b"\0" + data
    ).hexdigest()

def decode(name: str) -> bytes:
    return zlib.decompress(base64.b64decode(FULL_PAYLOADS[name]))

def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("root", nargs="?", type=Path, default=Path("."))
    args = ap.parse_args()
    root = args.root.expanduser().resolve()

    paths = {name: (root / name).resolve() for name in EXPECTED}
    originals = {}
    replacements = {}

    # Validate all source blobs before touching anything.
    for name, expected in EXPECTED.items():
        path = paths[name]
        if not path.is_file():
            raise SystemExit(f"missing target: {path}")
        data = path.read_bytes()
        actual = git_blob_sha(data)
        if actual != expected:
            raise SystemExit(
                f"refusing to patch {name}: expected blob {expected}, got {actual}"
            )
        originals[name] = data

    # Full replacements generated from the previous patched state.
    for name in FULL_PAYLOADS:
        data = decode(name)
        actual = git_blob_sha(data)
        if actual != FULL_NEW_SHA[name]:
            raise SystemExit(
                f"embedded replacement integrity failure for {name}: {actual}"
            )
        replacements[name] = data

    # Small exact transformation for the unchanged legacy confidence helper.
    legacy_name = "spline_dynamics_confidence.py"
    text = originals[legacy_name].decode("utf-8")
    for old, new in LEGACY_REPLACEMENTS:
        count = text.count(old)
        if count != 1:
            raise SystemExit(
                f"expected exactly one occurrence in {legacy_name}, found {count}: {old!r}"
            )
        text = text.replace(old, new, 1)
    replacements[legacy_name] = text.encode("utf-8")

    # Preflight compile every Python replacement before writes.
    with tempfile.TemporaryDirectory(prefix="grape-singular-fix-") as td:
        td = Path(td)
        for name, data in replacements.items():
            if name.endswith(".py"):
                tmp = td / Path(name).name
                tmp.write_bytes(data)
                py_compile.compile(str(tmp), doraise=True)

    written = []
    try:
        for name, data in replacements.items():
            path = paths[name]
            tmp = path.with_name(path.name + ".patch-tmp")
            tmp.write_bytes(data)
            os.replace(tmp, path)
            written.append(name)

        # Verify no ordinary inverse remains in the two relevant numerical paths.
        dyn_text = paths["../src/grape_param_estim/dynamics.py"].read_text(encoding="utf-8")
        conf_text = paths["spline_dynamics_confidence.py"].read_text(encoding="utf-8")
        if "np.linalg.inv(parameters.inertia)" in dyn_text:
            raise RuntimeError("ordinary inertia inverse still present")
        if "np.linalg.inv(prior_precision)" in conf_text:
            raise RuntimeError("ordinary prior precision inverse still present")
        if "np.linalg.inv(posterior_precision)" in conf_text:
            raise RuntimeError("ordinary posterior precision inverse still present")

        subprocess.run(
            [
                "git", "diff", "--check", "--",
                "deterministic_savgol_dynamics_estimator.py",
                "savgol_dynamics_confidence.py",
                "spline_dynamics_confidence.py",
                "deterministic_savgol_dynamics_data_dictionary.md",
                "../src/grape_param_estim/dynamics.py",
            ],
            cwd=root,
            check=True,
        )
    except Exception:
        for name in written:
            paths[name].write_bytes(originals[name])
        raise

    print("patched singular numerical paths and optimizer invalid-trial handling")
    print("  inertia ordinary inv -> pinv")
    print("  prior/posterior precision inv -> pinv")
    print("  posterior mean solve -> pinv covariance @ information vector")
    print("  invalid optimizer trial -> rejected numerically, recorded in diagnostics")
    print("  physical parameter bounds added: none")
    print("  backup files created: none")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
